function render(ctx) {
  const p = ctx.parameters || {};
  const speedMultiplier = Number.isFinite(p.speed_multiplier) ? Math.max(0.25, Math.min(2.5, p.speed_multiplier)) : 1;
  const orbitScale = Number.isFinite(p.orbit_scale) ? Math.max(0.75, Math.min(1.2, p.orbit_scale)) : 1;
  const accentInput = p.accent_color;
  const accentColor = typeof accentInput === 'string' && /^#[0-9A-Fa-f]{6}$/.test(accentInput) ? accentInput : '#FF786B';
  const width = Math.max(1, Number(ctx.width));
  const height = Math.max(1, Number(ctx.height));
  const timeValue = Number.isFinite(Number(ctx.time)) ? Number(ctx.time) : 0;
  const unit = Math.min(width, height);
  const cx = width * 0.5;
  const cy = height * 0.37;
  const tau = Math.PI * 2;
  const time = timeValue * speedMultiplier;
  const baseRadius = unit * 0.285 * orbitScale;
  const radii = [baseRadius * 0.38, baseRadius * 0.66, baseRadius];
  const cyan = '#43D9E8';
  const violet = '#A98BFA';
  const coralLight = '#FF9A82';
  const orbitColors = [cyan, violet, accentColor];
  const directions = [1, -1, 1];
  const phases = [time * 0.23, time * -0.36, time * 0.16];
  const commands = [];

  commands.push({ kind: 'rect', x: 0, y: 0, width: width, height: height, fill: '#071426' });
  commands.push({ kind: 'ellipse', x: cx - unit * 0.44, y: cy - unit * 0.30, width: unit * 0.88, height: unit * 0.60, fill: '#0A1D32', opacity: 0.42 });
  commands.push({ kind: 'ellipse', x: cx - unit * 0.34, y: cy - unit * 0.23, width: unit * 0.68, height: unit * 0.46, fill: '#0C2239', opacity: 0.22 });

  function ringPoints(radius, segments) {
    const points = [];
    for (let i = 0; i <= segments; i++) {
      const angle = i / segments * tau;
      points.push([cx + Math.cos(angle) * radius, cy + Math.sin(angle) * radius]);
    }
    return points;
  }

  for (let orbit = 0; orbit < 3; orbit++) {
    commands.push({ kind: 'line', points: ringPoints(radii[orbit], 96), stroke: orbitColors[orbit], stroke_width: 4.5 - orbit * 0.6, opacity: 0.07 });
    commands.push({ kind: 'line', points: ringPoints(radii[orbit], 96), stroke: orbitColors[orbit], stroke_width: 0.75 + orbit * 0.18, opacity: 0.62 });
  }

  for (let marker = 0; marker < 8; marker++) {
    const angle = phases[2] + marker * tau / 8;
    const length = unit * (marker % 2 === 0 ? 0.010 : 0.007);
    const innerRadius = radii[2] + unit * 0.005;
    const outerRadius = innerRadius + length;
    commands.push({
      kind: 'line',
      points: [
        [cx + Math.cos(angle) * innerRadius, cy + Math.sin(angle) * innerRadius],
        [cx + Math.cos(angle) * outerRadius, cy + Math.sin(angle) * outerRadius]
      ],
      stroke: marker % 3 === 0 ? cyan : accentColor,
      stroke_width: 0.9,
      opacity: marker % 2 === 0 ? 0.24 : 0.15
    });
  }

  for (let orbit = 0; orbit < 3; orbit++) {
    for (let bead = 1; bead <= 2; bead++) {
      const angle = phases[orbit] - directions[orbit] * bead * 0.038;
      const diameter = unit * (0.0038 - bead * 0.0008) * (1 + orbit * 0.1);
      commands.push({
        kind: 'ellipse',
        x: cx + Math.cos(angle) * radii[orbit] - diameter / 2,
        y: cy + Math.sin(angle) * radii[orbit] - diameter / 2,
        width: diameter,
        height: diameter,
        fill: orbitColors[orbit],
        opacity: 0.20 - bead * 0.06
      });
    }
  }

  function addSatellite(kind, x, y, size, color, rotation, opacity) {
    const cosA = Math.cos(rotation);
    const sinA = Math.sin(rotation);
    if (kind === 'circle') {
      commands.push({ kind: 'ellipse', x: x - size / 2, y: y - size / 2, width: size, height: size, fill: color, stroke: '#071426', stroke_width: Math.max(0.7, size * 0.1), opacity: opacity });
      return;
    }
    if (kind === 'ring') {
      const diameter = size * 1.18;
      commands.push({ kind: 'ellipse', x: x - diameter / 2, y: y - diameter / 2, width: diameter, height: diameter, fill: '#071426', stroke: color, stroke_width: Math.max(1, size * 0.09), opacity: opacity });
      return;
    }
    if (kind === 'diamond') {
      const local = [[0, -size * 0.58], [size * 0.38, 0], [0, size * 0.58], [-size * 0.38, 0]];
      const points = [];
      for (let i = 0; i < local.length; i++) {
        points.push([x + local[i][0] * cosA - local[i][1] * sinA, y + local[i][0] * sinA + local[i][1] * cosA]);
      }
      commands.push({ kind: 'polygon', points: points, fill: color, stroke: '#071426', stroke_width: 0.7, opacity: opacity });
      return;
    }
    if (kind === 'plus') {
      const thick = size * 0.30;
      const arm = size * 0.52;
      const local = [
        [-thick / 2, -arm], [thick / 2, -arm], [thick / 2, -thick / 2], [arm, -thick / 2],
        [arm, thick / 2], [thick / 2, thick / 2], [thick / 2, arm], [-thick / 2, arm],
        [-thick / 2, thick / 2], [-arm, thick / 2], [-arm, -thick / 2], [-thick / 2, -thick / 2]
      ];
      const points = [];
      for (let i = 0; i < local.length; i++) {
        points.push([x + local[i][0] * cosA - local[i][1] * sinA, y + local[i][0] * sinA + local[i][1] * cosA]);
      }
      commands.push({ kind: 'polygon', points: points, fill: color, stroke: '#071426', stroke_width: 0.7, opacity: opacity });
      return;
    }
    const points = [];
    for (let i = 0; i < 8; i++) {
      const angle = rotation + i * Math.PI / 4;
      const radius = i % 2 === 0 ? size * 0.62 : size * 0.22;
      points.push([x + Math.cos(angle) * radius, y + Math.sin(angle) * radius]);
    }
    commands.push({ kind: 'polygon', points: points, fill: color, stroke: '#071426', stroke_width: 0.7, opacity: opacity });
  }

  const counts = [4, 5, 6];
  const offsets = [0.2, 1.1, 2.3];
  const sizes = [unit * 0.0105, unit * 0.0115, unit * 0.0125];
  const kinds = ['circle', 'diamond', 'plus', 'star', 'ring', 'circle'];
  const satelliteColors = [cyan, violet, accentColor];

  for (let orbit = 0; orbit < 3; orbit++) {
    for (let index = 0; index < counts[orbit]; index++) {
      const angle = phases[orbit] + offsets[orbit] + index * tau / counts[orbit];
      const x = cx + Math.cos(angle) * radii[orbit];
      const y = cy + Math.sin(angle) * radii[orbit];
      const size = sizes[orbit] * (0.88 + 0.12 * Math.cos(index * 1.7 + orbit * 0.9));
      const kind = kinds[(index + orbit) % kinds.length];
      let color = satelliteColors[orbit];
      if (orbit === 2 && index % 2 === 1) color = coralLight;
      addSatellite(kind, x, y, size, color, angle + Math.PI * 0.25, 0.96);
    }
  }

  return commands;
}

